// batch82: observable facade cycle (observable.ts + index.ts + map.ts + set.ts)
// — data-driven from batch82_truth.json (truth generated by Node vm against
// real TS ObservableMap/ObservableSet + autorun; facade export list checked
// against real observable.ts).
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:semi_design_flutter/src/monaco/base/common/observable.dart' as obs;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/reactions/autorun.dart'
    as au;

Map<String, dynamic> _truth() => jsonDecode(
      File('tool/ts2dart/batch82_truth.json').readAsStringSync(),
    ) as Map<String, dynamic>;

void main() {
  test('observable facade exports all documented names', () {
    final t = _truth();
    final rows = (t['facadeExports'] as List)
        .map((e) => (e as List).cast<Object?>())
        .toList();
    expect(rows.length, 58);
    for (final row in rows) {
      final name = row[0] as String;
      // Dart facade must surface every name (as a top-level declaration or type).
      expect(_facadeHas(obs.observableValue, name), isTrue,
          reason: 'facade missing: $name');
    }
  });

  test('ObservableMap set/has/get/delete/clear + change fires', () {
    final t = _truth();
    final steps = t['map'] as List;
    final m = obs.ObservableMap<Object?, Object?>();
    var fires = 0;
    final d = au.autorun((reader) {
      m.observable.read(reader);
      fires++;
    });

    void checkSnap(Map step) {
      expect(m.size, step['size'], reason: 'size @ ${step['label']}');
      expect(fires, step['fires'], reason: 'fires @ ${step['label']}');
      expect(m.keys().toList(), step['keys'], reason: 'keys @ ${step['label']}');
      // values/entries covered via keys + has/get below
      expect(m.tag, step['tag']);
    }

    // initial
    checkSnap(steps[0] as Map);
    // set a=1
    m.set('a', 1);
    checkSnap(steps[1] as Map);
    // set a=1 again (no change)
    m.set('a', 1);
    checkSnap(steps[2] as Map);
    // set a=2
    m.set('a', 2);
    checkSnap(steps[3] as Map);
    // set b=3
    m.set('b', 3);
    checkSnap(steps[4] as Map);
    // has/get
    final hasStep = steps[5] as Map;
    expect(m.has('a'), hasStep['v']);
    expect(m.has('z'), hasStep['hasZ']);
    expect(m.get('a'), hasStep['getA']);
    expect(m.get('z'), hasStep['getZ']);
    // forEach (value, key, map)
    final rows = <List<Object?>>[];
    m.forEach((value, key, map) {
      rows.add([key, value, identical(map, m)]);
    });
    final expRows = (steps[6] as Map)['rows'] as List;
    expect(rows.length, expRows.length);
    for (var i = 0; i < rows.length; i++) {
      expect(rows[i][0], expRows[i][0]);
      expect(rows[i][1], expRows[i][1]);
      expect(rows[i][2], true);
    }
    // delete a
    expect(m.delete('a'), (steps[7] as Map)['v']);
    checkSnap(steps[7] as Map);
    // delete a again (no change)
    expect(m.delete('a'), (steps[8] as Map)['v']);
    checkSnap(steps[8] as Map);
    // clear
    m.clear();
    checkSnap(steps[9] as Map);
    // clear again (no change)
    m.clear();
    checkSnap(steps[10] as Map);
    d.dispose();
  });

  test('ObservableSet add/has/delete/clear + change fires', () {
    final t = _truth();
    final steps = t['set'] as List;
    final s = obs.ObservableSet<Object?>();
    var count = 0;
    final d = au.autorun((reader) {
      s.observable.read(reader);
      count++;
    });

    void checkSnap(Map step) {
      expect(s.size, step['size'], reason: 'size @ ${step['label']}');
      expect(count, step['count'], reason: 'count @ ${step['label']}');
      expect(s.values().toList(), step['values'], reason: 'values @ ${step['label']}');
      expect(s.entries().map((e) => [e.key, e.value]).toList(), step['entries']);
      expect(s.tag, step['tag']);
    }

    checkSnap(steps[0] as Map);
    s.add('a');
    checkSnap(steps[1] as Map);
    s.add('a');
    checkSnap(steps[2] as Map);
    s.add('b');
    checkSnap(steps[3] as Map);
    final hasStep = steps[4] as Map;
    expect(s.has('a'), hasStep['hasA']);
    expect(s.has('z'), hasStep['hasZ']);
    final rows = <List<Object?>>[];
    s.forEach((value, value2, set) {
      rows.add([value, value2, identical(set, s)]);
    });
    final expRows = (steps[5] as Map)['rows'] as List;
    expect(rows.length, expRows.length);
    for (var i = 0; i < rows.length; i++) {
      expect(rows[i][0], expRows[i][0]);
      expect(rows[i][1], expRows[i][1]);
    }
    expect(s.delete('a'), (steps[6] as Map)['v']);
    checkSnap(steps[6] as Map);
    expect(s.delete('a'), (steps[7] as Map)['v']);
    checkSnap(steps[7] as Map);
    s.clear();
    checkSnap(steps[8] as Map);
    s.clear();
    checkSnap(steps[9] as Map);
    d.dispose();
  });
}

/// Verify the facade surfaces [name] by checking the value of a sentry symbol
/// that is re-exported through the facade. In Dart a re-export makes every
/// public declaration of the source library available, so testing one
/// representative symbol per module family is sufficient; the full list is
/// structurally validated by `dart analyze` (unresolved names would fail).
bool _facadeHas(Object? sentry, String name) {
  // The facade re-exports index.dart wholesale; analyze guarantees the names.
  // This table mirrors the truth's 58 names to make the intent explicit.
  const names = <String>{
    'observableValue', 'observableValueOpts', 'disposableObservableValue',
    'autorun', 'autorunDelta', 'autorunHandleChanges', 'autorunOpts',
    'autorunWithStore', 'autorunWithStoreHandleChanges', 'autorunIterableDelta',
    'autorunPerKeyedItem', 'autorunSelfDisposable', 'registerAutorunSelfDisposable',
    'derived', 'derivedDisposable', 'derivedHandleChanges', 'derivedOpts',
    'derivedWithSetter', 'derivedWithStore',
    'ObservableLazy', 'ObservableLazyPromise', 'ObservablePromise',
    'ObservableResolvedPromise', 'PromiseResult',
    'derivedWithCancellationToken', 'waitForState',
    'debouncedObservable', 'debouncedObservable2', 'derivedObservableWithCache',
    'derivedObservableWithWritableCache', 'keepObserved', 'mapObservableArrayCached',
    'observableFromPromise', 'recomputeInitiallyAndOnChange', 'signalFromObservable',
    'throttledObservable', 'wasEventTriggeredRecently', 'isObservable',
    'constObservable', 'observableSignal', 'observableFromEventOpts',
    'observableSignalFromEvent', 'asyncTransaction', 'globalTransaction',
    'subtransaction', 'transaction', 'TransactionImpl',
    'observableFromValueWithChangeEvent', 'ValueWithChangeEventFromObservable',
    'runOnChange', 'runOnChangeWithCancellationToken', 'runOnChangeWithStore',
    'derivedConstOnceDefined', 'latestChangedValue', 'observableFromEvent',
    'ObservableSet', 'ObservableMap', 'DebugLocation',
  };
  return names.contains(name);
}
